-- Modify "agent_run_inputs" table
ALTER TABLE "procurement"."agent_run_inputs" DROP CONSTRAINT "agent_run_inputs_message_check", ADD CONSTRAINT "agent_run_inputs_message_check" CHECK ((char_length(buyer_message) <= 2000) AND (buyer_message !~ '^[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]|[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]$'::text)), ADD CONSTRAINT "agent_run_inputs_answer_check" CHECK ((option_id IS NULL) = (char_length(buyer_message) >= 1)), ADD CONSTRAINT "agent_run_inputs_option_check" CHECK ((option_id IS NULL) OR ((char_length(option_id) >= 1) AND (char_length(option_id) <= 200) AND (option_id !~ '^[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]|[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]$'::text))), ADD COLUMN "option_id" text NULL;
-- Modify "agent_runs" table
ALTER TABLE "procurement"."agent_runs" DROP CONSTRAINT "agent_runs_failure_check", ADD CONSTRAINT "agent_runs_failure_check" CHECK ((failure_reason IS NULL) OR (failure_reason = ANY (ARRAY['WORKER_LOST'::text, 'SEARCH_FAILED'::text, 'TURN_PIPELINE_ERROR'::text, 'MODEL_UNAVAILABLE'::text, 'ITEM_CATEGORY_UNAVAILABLE'::text, 'ANSWER_REJECTED'::text])));
